macro_rules! deps {
    () => {
        PikeVM!();
        Captures!();
        Input!();
        Span!();
    };
}

macro_rules! Searcher {
    () => {
        deps!();
        # [doc = " A searcher for creating iterators and performing lower level iteration."] # [doc = ""] # [doc = " This searcher encapsulates the logic required for finding all successive"] # [doc = " non-overlapping matches in a haystack. In theory, iteration would look"] # [doc = " something like this:"] # [doc = ""] # [doc = " 1. Setting the start position to `0`."] # [doc = " 2. Execute a regex search. If no match, end iteration."] # [doc = " 3. Report the match and set the start position to the end of the match."] # [doc = " 4. Go back to (2)."] # [doc = ""] # [doc = " And if this were indeed the case, it's likely that `Searcher` wouldn't"] # [doc = " exist. Unfortunately, because a regex may match the empty string, the above"] # [doc = " logic won't work for all possible regexes. Namely, if an empty match is"] # [doc = " found, then step (3) would set the start position of the search to the"] # [doc = " position it was at. Thus, iteration would never end."] # [doc = ""] # [doc = " Instead, a `Searcher` knows how to detect these cases and forcefully"] # [doc = " advance iteration in the case of an empty match that overlaps with a"] # [doc = " previous match."] # [doc = ""] # [doc = " If you know that your regex cannot match any empty string, then the simple"] # [doc = " algorithm described above will work correctly."] # [doc = ""] # [doc = " When possible, prefer the iterators defined on the regex engine you're"] # [doc = " using. This tries to abstract over the regex engine and is thus a bit more"] # [doc = " unwieldy to use."] # [doc = ""] # [doc = " In particular, a `Searcher` is not itself an iterator. Instead, it provides"] # [doc = " `advance` routines that permit moving the search along explicitly. It also"] # [doc = " provides various routines, like [`Searcher::into_matches_iter`], that"] # [doc = " accept a closure (representing how a regex engine executes a search) and"] # [doc = " returns a conventional iterator."] # [doc = ""] # [doc = " The lifetime parameters come from the [`Input`] type passed to"] # [doc = " [`Searcher::new`]:"] # [doc = ""] # [doc = " * `'h` is the lifetime of the underlying haystack."] # [doc = ""] # [doc = " # Searcher vs Iterator"] # [doc = ""] # [doc = " Why does a search type with \"advance\" APIs exist at all when we also have"] # [doc = " iterators? Unfortunately, the reasoning behind this split is a complex"] # [doc = " combination of the following things:"] # [doc = ""] # [doc = " 1. While many of the regex engines expose their own iterators, it is also"] # [doc = " nice to expose this lower level iteration helper because it permits callers"] # [doc = " to provide their own `Input` configuration. Moreover, a `Searcher` can work"] # [doc = " with _any_ regex engine instead of only the ones defined in this crate."] # [doc = " This way, everyone benefits from a shared iteration implementation."] # [doc = " 2. There are many different regex engines that, while they have the same"] # [doc = " match semantics, they have slightly different APIs. Iteration is just"] # [doc = " complex enough to want to share code, and so we need a way of abstracting"] # [doc = " over those different regex engines. While we could define a new trait that"] # [doc = " describes any regex engine search API, it would wind up looking very close"] # [doc = " to a closure. While there may still be reasons for the more generic trait"] # [doc = " to exist, for now and for the purposes of iteration, we use a closure."] # [doc = " Closures also provide a lot of easy flexibility at the call site, in that"] # [doc = " they permit the caller to borrow any kind of state they want for use during"] # [doc = " each search call."] # [doc = " 3. As a result of using closures, and because closures are anonymous types"] # [doc = " that cannot be named, it is difficult to encapsulate them without both"] # [doc = " costs to speed and added complexity to the public API. For example, in"] # [doc = " defining an iterator type like"] # [doc = " [`dfa::regex::FindMatches`](crate::dfa::regex::FindMatches),"] # [doc = " if we use a closure internally, it's not possible to name this type in the"] # [doc = " return type of the iterator constructor. Thus, the only way around it is"] # [doc = " to erase the type by boxing it and turning it into a `Box<dyn FnMut ...>`."] # [doc = " This boxed closure is unlikely to be inlined _and_ it infects the public"] # [doc = " API in subtle ways. Namely, unless you declare the closure as implementing"] # [doc = " `Send` and `Sync`, then the resulting iterator type won't implement it"] # [doc = " either. But there are practical issues with requiring the closure to"] # [doc = " implement `Send` and `Sync` that result in other API complexities that"] # [doc = " are beyond the scope of this already long exposition."] # [doc = " 4. Some regex engines expose more complex match information than just"] # [doc = " \"which pattern matched\" and \"at what offsets.\" For example, the PikeVM"] # [doc = " exposes match spans for each capturing group that participated in the"] # [doc = " match. In such cases, it can be quite beneficial to reuse the capturing"] # [doc = " group allocation on subsequent searches. A proper iterator doesn't permit"] # [doc = " this API due to its interface, so it's useful to have something a bit lower"] # [doc = " level that permits callers to amortize allocations while also reusing a"] # [doc = " shared implementation of iteration. (See the documentation for"] # [doc = " [`Searcher::advance`] for an example of using the \"advance\" API with the"] # [doc = " PikeVM.)"] # [doc = ""] # [doc = " What this boils down to is that there are \"advance\" APIs which require"] # [doc = " handing a closure to it for every call, and there are also APIs to create"] # [doc = " iterators from a closure. The former are useful for _implementing_"] # [doc = " iterators or when you need more flexibility, while the latter are useful"] # [doc = " for conveniently writing custom iterators on-the-fly."] # [doc = ""] # [doc = " # Example: iterating with captures"] # [doc = ""] # [doc = " Several regex engines in this crate over convenient iterator APIs over"] # [doc = " [`Captures`] values. To do so, this requires allocating a new `Captures`"] # [doc = " value for each iteration step. This can perhaps be more costly than you"] # [doc = " might want. Instead of implementing your own iterator to avoid that"] # [doc = " cost (which can be a little subtle if you want to handle empty matches"] # [doc = " correctly), you can use this `Searcher` to do it for you:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     nfa::thompson::pikevm::PikeVM,"] # [doc = "     util::iter::Searcher,"] # [doc = "     Input, Span,"] # [doc = " };"] # [doc = ""] # [doc = " let re = PikeVM::new(\"foo(?P<numbers>[0-9]+)\")?;"] # [doc = " let haystack = \"foo1 foo12 foo123\";"] # [doc = ""] # [doc = " let mut caps = re.create_captures();"] # [doc = " let mut cache = re.create_cache();"] # [doc = " let mut matches = vec![];"] # [doc = " let mut searcher = Searcher::new(Input::new(haystack));"] # [doc = " while let Some(_) = searcher.advance(|input| {"] # [doc = "     re.search(&mut cache, input, &mut caps);"] # [doc = "     Ok(caps.get_match())"] # [doc = " }) {"] # [doc = "     // The unwrap is OK since 'numbers' matches if the pattern matches."] # [doc = "     matches.push(caps.get_group_by_name(\"numbers\").unwrap());"] # [doc = " }"] # [doc = " assert_eq!(matches, vec!["] # [doc = "     Span::from(3..4),"] # [doc = "     Span::from(8..10),"] # [doc = "     Span::from(14..17),"] # [doc = " ]);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug)] pub struct Searcher < 'h > { # [doc = " The input parameters to give to each regex engine call."] # [doc = ""] # [doc = " The start position of the search is mutated during iteration."] input : Input < 'h > , # [doc = " Records the end offset of the most recent match. This is necessary to"] # [doc = " handle a corner case for preventing empty matches from overlapping with"] # [doc = " the ending bounds of a prior match."] last_match_end : Option < usize > , }
    };
}

Searcher!()